Steps:
[GQL-ENDPOINT /graphql/sales-rep]
[AUTH role=SALES_REP]
[GQL-OP list_new]
  query { salesRepOrders(organizationId: "{{org}}", storeId: "{{store}}", filter: "New") { totalCount } }
[GQL-EXEC list_new]
[GQL-CAPTURE list_new.data.salesRepOrders.totalCount → NEW_LIST_COUNT]
[GQL-OP stats_wide]
  query {
    salesRepCustomerOrderStatistics(storeId: "{{store}}", organizationId: "{{org}}") {
      new_count: period(from: "{{wide_from}}", to: "{{wide_to}}", filter: "New") { count }
      all_count: period(from: "{{wide_from}}", to: "{{wide_to}}") { count }
      cancelled_count: period(from: "{{wide_from}}", to: "{{wide_to}}", filter: "Cancelled") { count }
    }
  }
[GQL-EXEC stats_wide]

Assertions:
[ERRORS label=list_new] errors[] empty {SPEC}
[ERRORS label=stats_wide] errors[] empty {SPEC}
[DATA label=stats_wide] data.salesRepCustomerOrderStatistics.new_count.count = {{NEW_LIST_COUNT}} {SPEC}
[COUNT label=stats_wide] data.salesRepCustomerOrderStatistics.cancelled_count.count >= 1 {DOC}
[DATA label=stats_wide] data.salesRepCustomerOrderStatistics.all_count.count >= data.salesRepCustomerOrderStatistics.new_count.count {SPEC}
[DATA label=stats_wide] data.salesRepCustomerOrderStatistics.all_count.count >= data.salesRepCustomerOrderStatistics.new_count.count + data.salesRepCustomerOrderStatistics.cancelled_count.count {BL}

